  if (Op.getValueType() == MVT::bf16) {
    SDLoc Loc(Op);
    SDValue IntOp = Op.getOperand(0);
    EVT IntVT = IntOp.getValueType();
    SDValue F32 = DAG.getNode(Op.getOpcode(), Loc, MVT::f32, IntOp);

    // int -> f32 -> bf16 would double-round: i32/i64 don't fit in f32's 24-bit
    // significand, so the int->f32 step can be inexact and land on a bf16 tie
    // that then rounds the wrong way. Round the int->f32 step to odd
    // (Boldo/Melquiond) so the hardware f32 -> bf16 step is correctly rounded.
    // i1/i16 always convert to f32 exactly, so they keep the plain path.
    if (IntVT == MVT::i32 || IntVT == MVT::i64) {
      bool Signed = Op.getOpcode() == ISD::SINT_TO_FP;
      EVT CCVT = getSetCCResultType(DAG.getDataLayout(), *DAG.getContext(),
                                    IntVT);
      // F32 is integral here, so converting it back to the integer type is
      // exact; comparing with IntOp detects an inexact int->f32 conversion.
      SDValue Back = DAG.getNode(Signed ? ISD::FP_TO_SINT : ISD::FP_TO_UINT,
                                 Loc, IntVT, F32);
      SDValue Exact = DAG.getSetCC(Loc, CCVT, Back, IntOp, ISD::SETEQ);
      // Rounded toward zero iff |IntOp| > |Back|. The adjacent odd f32 is one
      // ULP up in magnitude (+1 in the bit pattern) if we rounded toward zero,
      // else one ULP down (-1).
      SDValue AbsInt = Signed ? DAG.getNode(ISD::ABS, Loc, IntVT, IntOp) : IntOp;
      SDValue AbsBack = Signed ? DAG.getNode(ISD::ABS, Loc, IntVT, Back) : Back;
      SDValue TowardZero = DAG.getSetCC(Loc, CCVT, AbsInt, AbsBack, ISD::SETUGT);
      SDValue Bits = DAG.getNode(ISD::BITCAST, Loc, MVT::i32, F32);
      SDValue One = DAG.getConstant(1, Loc, MVT::i32);
      SDValue Adjust = DAG.getSelect(Loc, MVT::i32, TowardZero, One,
                                     DAG.getAllOnesConstant(Loc, MVT::i32));
      SDValue Odd = DAG.getNode(ISD::ADD, Loc, MVT::i32, Bits, Adjust);
      // Keep round-to-nearest F32 if it was exact or is already odd.
      EVT I32CCVT = getSetCCResultType(DAG.getDataLayout(), *DAG.getContext(),
                                       MVT::i32);
      SDValue AlreadyOdd =
          DAG.getSetCC(Loc, I32CCVT, DAG.getNode(ISD::AND, Loc, MVT::i32, Bits,
                                                 One),
                       One, ISD::SETEQ);
      SDValue Keep = DAG.getNode(ISD::OR, Loc, CCVT, Exact, AlreadyOdd);
      Bits = DAG.getSelect(Loc, MVT::i32, Keep, Bits, Odd);
      F32 = DAG.getNode(ISD::BITCAST, Loc, MVT::f32, Bits);
    }

    return DAG.getNode(ISD::FP_ROUND, Loc, MVT::bf16, F32,
                       DAG.getIntPtrConstant(0, Loc, /*isTarget=*/true));
  }

  // Everything else is considered legal.
  return Op;
}

