auto ExtendBuffer = [](APInt Val, AggBuffer *Buffer) {
  // Round up so a width that isn't a multiple of 8 (e.g. i65) still emits its
  // top partial byte. `extractBitsAsZExtValue` cannot read past the bit
  // width, so the last byte is extracted with only the bits that remain.
  unsigned NumBytes = (Val.getBitWidth() + 7) / 8;
  for (unsigned I : llvm::seq(NumBytes)) {
    unsigned NumBits = std::min(8u, Val.getBitWidth() - I * 8);
    Buffer->addByte(Val.extractBitsAsZExtValue(NumBits, I * 8));
  }
};

