static bool canLowerToLDG(const MemSDNode &N, const NVPTXSubtarget &Subtarget,
                          NVPTX::AddressSpace CodeAddrSpace) {
  // We use ldg (i.e. ld.global.nc) for invariant loads from the global address
  // space. Atomic loads must keep their ordering and are not AtomicSDNodes that
  // ldg can represent, so never route them here (this also avoids reading the
  // MLoad-only mask/extension operands off an AtomicSDNode in tryLDG).
  return Subtarget.hasLDG() && CodeAddrSpace == NVPTX::AddressSpace::Global &&
         N.isInvariant() && N.getOpcode() != ISD::ATOMIC_LOAD;
}

