// A <N x i1> argument/return value occupies getTypeAllocSize() = ceil(N/8)
// bytes in its .param slot, with the elements packed one bit per element (the
// canonical in-memory layout). Pass it as a single packed integer of that many
// bytes so the generic CopyTo/FromParts bitcast handles the packing, instead of
// spreading one byte-wide register per element across offsets 0..N-1 and
// reading/writing past the end of the slot. Only handle widths whose packed
// size is a natural integer (1/2/4/8 bytes); other widths fall back to the
// default per-element breakdown.
static MVT getPackedI1VectorRegisterType(EVT VT) {
  if (VT.isSimple() && VT.isVector() && !VT.isScalableVector() &&
      VT.getVectorElementType() == MVT::i1 && VT.getVectorNumElements() >= 2) {
    const unsigned NumBytes = divideCeil(VT.getVectorNumElements(), 8);
    if (NumBytes == 1 || NumBytes == 2 || NumBytes == 4 || NumBytes == 8)
      return MVT::getIntegerVT(NumBytes * 8);
  }
  return MVT::INVALID_SIMPLE_VALUE_TYPE;
}

MVT NVPTXTargetLowering::getRegisterTypeForCallingConv(LLVMContext &Context,
                                                       CallingConv::ID CC,
                                                       EVT VT) const {
  if (MVT Packed = getPackedI1VectorRegisterType(VT);
      Packed != MVT::INVALID_SIMPLE_VALUE_TYPE)
    return Packed;
  return TargetLoweringBase::getRegisterTypeForCallingConv(Context, CC, VT);
}

unsigned NVPTXTargetLowering::getNumRegistersForCallingConv(
    LLVMContext &Context, CallingConv::ID CC, EVT VT) const {
  if (getPackedI1VectorRegisterType(VT) != MVT::INVALID_SIMPLE_VALUE_TYPE)
    return 1;
  return TargetLoweringBase::getNumRegistersForCallingConv(Context, CC, VT);
}

