NVPTX::AddressSpace
NVPTXDAGToDAGISel::getAtomicAddrSpace(const MemSDNode *N) {
  // PTX 'atom' only supports the .global and .shared state spaces and generic
  // addressing; const/local/param have no atom qualifier and their addresses
  // are window-relative, so they cannot be reinterpreted as generic.
  auto AS = getAddrSpace(N);
  switch (AS) {
  case NVPTX::AddressSpace::Generic:
  case NVPTX::AddressSpace::Global:
  case NVPTX::AddressSpace::Shared:
  case NVPTX::AddressSpace::SharedCluster:
    return AS;
  case NVPTX::AddressSpace::Const:
  case NVPTX::AddressSpace::Local:
  case NVPTX::AddressSpace::EntryParam:
  case NVPTX::AddressSpace::DeviceParam:
    report_fatal_error(
        formatv("PTX does not support atomic operations on the {} address "
                "space (only .global, .shared, and generic are supported): {}",
                NVPTX::addressSpaceToString(AS), N->getOperationName()));
  }
  llvm_unreachable("Unexpected address space");
}

