bool NVPTXAtomicLower::runOnFunction(Function &F) {
  SmallVector<AtomicRMWInst *> LocalMemoryAtomics;
  for (Instruction &I : instructions(F))
    if (AtomicRMWInst *RMWI = dyn_cast<AtomicRMWInst>(&I))
      if (RMWI->getPointerAddressSpace() == ADDRESS_SPACE_LOCAL)
        LocalMemoryAtomics.push_back(RMWI);

  bool Changed = false;
  for (AtomicRMWInst *RMWI : LocalMemoryAtomics)
    Changed |= lowerAtomicRMWInst(RMWI);
  return Changed;
}

edits.new_string:
bool NVPTXAtomicLower::runOnFunction(Function &F) {
  // Local memory is thread-private, so atomics on it cannot race and PTX has no
  // atom qualifier for the .local state space. Rewrite them to plain
  // load/store. cmpxchg is handled in addition to atomicrmw because both reach
  // the invalid atom.local.* selection otherwise.
  SmallVector<AtomicRMWInst *> LocalMemoryRMWs;
  SmallVector<AtomicCmpXchgInst *> LocalMemoryCmpXchgs;
  for (Instruction &I : instructions(F)) {
    if (AtomicRMWInst *RMWI = dyn_cast<AtomicRMWInst>(&I)) {
      if (RMWI->getPointerAddressSpace() == ADDRESS_SPACE_LOCAL)
        LocalMemoryRMWs.push_back(RMWI);
    } else if (AtomicCmpXchgInst *CXI = dyn_cast<AtomicCmpXchgInst>(&I)) {
      if (CXI->getPointerAddressSpace() == ADDRESS_SPACE_LOCAL)
        LocalMemoryCmpXchgs.push_back(CXI);
    }
  }

  bool Changed = false;
  for (AtomicRMWInst *RMWI : LocalMemoryRMWs)
    Changed |= lowerAtomicRMWInst(RMWI);
  for (AtomicCmpXchgInst *CXI : LocalMemoryCmpXchgs)
    Changed |= lowerAtomicCmpXchgInst(CXI);
  return Changed;
}

