NVPTX::AddressSpace
NVPTXDAGToDAGISel::getAtomicAddrSpace(const MemSDNode *N) const {
  // PTX 'atom' only supports the .global and .shared state spaces and generic
  // addressing; const/local/param have no atom qualifier and their addresses
  // are window-relative, so they cannot be reinterpreted as generic.
  auto AS = getAddrSpace(N);
  switch (AS) {
  case NVPTX::AddressSpace::SharedCluster:
    // The .shared::cluster qualifier only exists on sm_90+ / PTX 7.8+; emitting
    // it on older targets produces PTX that ptxas rejects.
    if (!Subtarget->hasClusters())
      report_fatal_error(
          formatv("atomic operations on the {} address space require sm_90+ "
                  "and PTX 7.8+: {}",
                  NVPTX::addressSpaceToString(AS), N->getOperationName()));
